              <svg class="eye-closed" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="display:none"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94"/><path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/><line x1="1" y1="1" x2="23" y2="23"/></svg>
            </button>
          </div>
          <div class="field-msg" id="confirmMsg" aria-live="polite"></div>
        </div>

        <div class="checkbox-row">
          <input type="checkbox" id="tos" name="tos" required aria-describedby="tosMsg">
          <label for="tos">I agree to the <a href="#" onclick="return false">Terms of Service</a> and <a href="#" onclick="return false">Privacy Policy</a> <span class="req" aria-hidden="true">*</span></label>
        </div>
        <div class="field-msg error" id="tosMsg" aria-live="polite" style="grid-column:1/-1"></div>

        <button type="submit" class="btn-submit" id="submitBtn">Create Account</button>
