<script>
(function(){
  const $=id=>document.getElementById(id);
  const REGISTRY_KEY='reg_users_v1';
  let lockout=0;

  const fields=[
    {id:'username',label:'Username'},
    {id:'email',label:'Email'},
    {id:'dob',label:'Date of birth'},
    {id:'password',label:'Password'},
    {id:'passwordConfirm',label:'Confirm password'},
    {id:'tos',label:'Terms acceptance'}
  ];

  // Set max date for dob
  const today=new Date();
  $('dob').max=today.toISOString().split('T')[0];

  function getUsers(){try{return JSON.parse(localStorage.getItem(REGISTRY_KEY))||[]}catch{return[]}}

  function normalizeUser(u){
    return{
      username:u.username.trim().toLowerCase(),
      email:u.email.trim().toLowerCase()
    };
  }

  // Validation helpers
  const usernameValid=v=>/^[A-Za-z0-9_-]{3,30}$/.test(v);
  const emailValid=v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
  const dobValid=v=>{
    if(!v)return true; // optional
    const d=new Date(v+'T00:00:00');
    if(isNaN(d.getTime()))return false;
    const age=(today-d)/(365.25*24*3600*1000);
    return age>=13&&age<=150;
  };

  function pwScore(p){
    let s=0;
    if(p.length>=8)s++;
    if(p.length>=12)s++;
    if(/[A-Z]/.test(p))s++;
    if(/[0-9]/.test(p))s++;
    if(/[^A-Za-z0-9]/.test(p))s++;
    return s;
  }

  function setMsg(id,msg,type){
    const el=$(id);
    el.textContent=msg;
    el.className='field-msg'+(type?' '+type:'');
  }

  function setInvalid(id,invalid){
    const el=$(id);
    if(invalid)el.setAttribute('aria-invalid','true');
    else el.removeAttribute('aria-invalid');
  }

  function showGlobal(msg,type){
    const el=$('globalAlert');
    el.textContent=msg;
    el.className='alert visible '+type;
  }
  function hideGlobal(){$('globalAlert').className='alert'}

  // Password toggle
  document.querySelectorAll('.pw-toggle').forEach(btn=>{
    btn.addEventListener('click',function(){
      const t=$(this.dataset.target);
      const isHidden=t.type==='password';
      t.type=isHidden?'text':'password';
      this.setAttribute('aria-label',isHidden?'Hide password':'Show password');
      this.querySelector('.eye-open').style.display=isHidden?'none':'block';
      this.querySelector('.eye-closed').style.display=isHidden?'block':'none';
    });
  });

  // Password strength
  $('password').addEventListener('input',function(){
    const v=this.value;
    const s=pwScore(v);
    const bar=$('strengthBar');
    const lbl=$('strengthLabel');
    if(!v){bar.style.width='0%';lbl.textContent='';return;}
    const pct=[20,40,60,80,100][s-1]||0;
    const colors=['#c0392b','#e67e22','#f1c40f','#27ae60','#1a7a3a'];
    const labels=['Very weak','Weak','Fair','Strong','Very strong'];
    bar.style.width=pct+'%';
    bar.style.background=colors[s-1];
    lbl.textContent='Strength: '+labels[s-1];
    // re-check confirm if filled
    if($('passwordConfirm').value)validateField('passwordConfirm');
  });

  // Validate a single field, returns true if valid
  function validateField(id){
    const v=$(id).value;
    switch(id){
      case 'username':{
        if(!v){setMsg(id+'Msg','Username is required.','error');setInvalid(id,true);return false;}
        if(!usernameValid(v)){setMsg(id+'Msg','Use 3–30 characters: letters, numbers, _ or -.','error');setInvalid(id,true);return false;}
        const users=getUsers();
        if(users.some(u=>normalizeUser(u).username===v.trim().toLowerCase())){
          setMsg(id+'Msg','This username is already taken.','error');setInvalid(id,true);return false;
        }
        setMsg(id+'Msg','✓ Looks good.','ok');setInvalid(id,false);return true;
      }
      case 'email':{
        if(!v){setMsg(id+'Msg','Email address is required.','error');setInvalid(id,true);return false;}
        if(!emailValid(v)){setMsg(id+'Msg','Please enter a valid email address.','error');setInvalid(id,true);return false;}
        const users=getUsers();
        if(users.some(u=>normalizeUser(u).email===v.trim().toLowerCase())){
          setMsg(id+'Msg','An account with this email already exists.','error');setInvalid(id,true);return false;
        }
        setMsg(id+'Msg','✓ Looks good.','ok');setInvalid(id,false);return true;
      }
      case 'dob':{
        if(!v){setMsg(id+'Msg','',null);setInvalid(id,false);return true;}
        if(!dobValid(v)){setMsg(id+'Msg','You must be at least 13 years old to register.','error');setInvalid(id,true);return false;}
        setMsg(id+'Msg','',null);setInvalid(id,false);return true;
      }
      case 'password':{
        if(!v){setMsg(id+'Msg','Password is required.','error');setInvalid(id,true);return false;}
        if(v.length<8){setMsg(id+'Msg','Password must be at least 8 characters.','error');setInvalid(id,true);return false;}
        setMsg(id+'Msg','✓ Acceptable.','ok');setInvalid(id,false);return true;
      }
      case 'passwordConfirm':{
        const pw=$('password').value;
        if(!v){setMsg(id+'Msg','Please confirm your password.','error');setInvalid(id,true);return false;}
        if(v!==pw){setMsg(id+'Msg','Passwords do not match.','error');setInvalid(id,true);return false;}
        setMsg(id+'Msg','✓ Match.','ok');setInvalid(id,false);return true;
      }
      case 'tos':{
        if(!$('tos').checked){$('tosMsg').textContent='You must accept the terms to register.';return false;}
        $('tosMsg').textContent='';return true;
      }
    }
    return true;
  }

  // Blur validation
  ['username','email','dob','password','passwordConfirm'].forEach(id=>{
    $(id).addEventListener('blur',()=>validateField(id));
  });
  $('tos').addEventListener('change',()=>validateField('tos'));

  // Submit
  $('regForm').addEventListener('submit',function(e){
    e.preventDefault();
    if(Date.now()<lockout){showGlobal('Too many attempts. Please wait a moment.','error');return;}
    hideGlobal();
    let valid=true;
    let firstInvalid=null;
    fields.forEach(f=>{
      if(!validateField(f.id)){
        valid=false;
        if(!firstInvalid)firstInvalid=f.id;
      }
    });
    if(!valid){
      showGlobal('Please fix the highlighted errors before submitting.','error');
      if(firstInvalid){
        const el=$(firstInvalid);
        if(el.type==='checkbox')el.focus();else el.focus();
      }
      return;
    }

    const username=$('username').value.trim();
    const email=$('email').value.trim().toLowerCase();
    const dob=$('dob').value||null;

    const users=getUsers();
    // Duplicate check (race-safe)
    if(users.some(u=>normalizeUser(u).username===username.toLowerCase())||
       users.some(u=>normalizeUser(u).email===email)){
      showGlobal('This username or email is already registered. Please choose different values.','error');
      lockout=Date.now()+3000;
      validateField('username');
      validateField('email');
      return;
    }

    users.push({username:username.trim(),email:email,dob:dob,ts:Date.now()});
    try{localStorage.setItem(REGISTRY_KEY,JSON.stringify(users))}catch(ex){}

    // Clear password fields immediately
    $('password').value='';
    $('passwordConfirm').value='';
    $('strengthBar').style.width='0%';
    $('strengthLabel').textContent='';
    ['passwordMsg','confirmMsg'].forEach(m=>setMsg(m,'',null));

    showGlobal('Registration successful! Your account has been created. You can now sign in.','success');
    this.reset();
    $('dob').max=today.toISOString().split('T')[0];
    fields.forEach(f=>setInvalid(f.id,false));
    fields.forEach(f=>{const m=$(f.id+'Msg');if(m){m.textContent='';m.className='field-msg';}});
    $('tosMsg').textContent='';
  });
})();
</script>
</body>
